/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
cache = Path('/workspace/__pycache__')
if cache.exists():
    for path in cache.iterdir():
        if path.name.startswith('openai_client.') and path.suffix == '.pyc':
            path.unlink()
    try:
        cache.rmdir()
    except OSError:
        pass
PY
find /workspace -maxdepth 2 -type f -print"

